function xorGame(nums) {
  // Exhaustive game search: the player to move tries wiping each distinct number still on the board.
  const onBoard = nums.map(() => true);
  const wins = total => {
    if (total === 0) return true;
    const tried = new Set();
    for (let i = 0; i < nums.length; i++) {
      if (!onBoard[i] || tried.has(nums[i])) continue;
      tried.add(nums[i]);
      const rest = total ^ nums[i];
      if (rest === 0) continue;
      onBoard[i] = false;
      const opponentWins = wins(rest);
      onBoard[i] = true;
      if (!opponentWins) return true;
    }
    return false;
  };
  return wins(nums.reduce((a, b) => a ^ b, 0));
}

