function generate(rand, size) {
  const n = size === 'large' ? 990 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 8);
  const limit = size === 'large' ? 65536 : (rand() < 0.5 ? 4 : 16);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * limit));
  // Sometimes force a total XOR of 0 so the immediate-win case appears with odd lengths too.
  if (rand() < 0.35) {
    let rest = 0;
    for (let i = 0; i < n - 1; i++) rest ^= nums[i];
    nums[n - 1] = rest;
  }
  return [nums];
}
